const fs=require('fs'),path=require('path'),cp=require('child_process'),crypto=require('crypto');
const base=__dirname,src=path.resolve(base,'../..'),results=[];
function setup(n){const r=path.join(base,'gov_r2_final_'+n);for(const d of ['tools','02_echipa','03_plan','05_validare','07_audit','09_jurnale'])fs.mkdirSync(path.join(r,d),{recursive:true});fs.copyFileSync(path.join(src,'tools/manage.cjs'),path.join(r,'tools/manage.cjs'));return r;}
function save(r,p,v){fs.writeFileSync(path.join(r,p),JSON.stringify(v,null,2));}
function run(r,args){const p=cp.spawnSync(process.execPath,[path.join(r,'tools/manage.cjs'),...args],{encoding:'utf8'});return {exit_code:p.status,stdout:p.stdout.trim(),stderr:p.stderr.trim().slice(0,450)};}
function probe(id,purpose,r,args){results.push({id,purpose,actual:run(r,args)});}
let r=setup('checkpoint');
fs.writeFileSync(path.join(r,'evidence.txt'),'fixture input');
const h=crypto.createHash('sha256').update('fixture input').digest('hex');
const good={actor:'actor',task:'W00',event:'checkpoint',result:'input verified',artifacts:['evidence.txt'],next:'independent review',attempt:1,input_hashes:{'evidence.txt':h},checks:['CHECK1: input SHA256 computed; evidence.txt']};
save(r,'input.json',good);probe('GOV2-F01','Valid structured checkpoint string checks and real hash',r,['event-json',path.join(r,'input.json')]);probe('GOV2-F02','Valid checkpoint log validates',r,['validate']);
r=setup('invalid_logged_checkpoint');fs.writeFileSync(path.join(r,'09_jurnale/actor.jsonl'),JSON.stringify({...good,schema_version:'1.1',event_id:'fixture',timestamp:new Date().toISOString(),input_hashes:{x:'banana'},checks:[false]})+'\n');probe('GOV2-F03','Invalid structured record inserted directly must fail validation',r,['validate']);
r=setup('positive_registers');fs.writeFileSync(path.join(r,'evidence.txt'),'fixture proof');fs.writeFileSync(path.join(r,'07_audit/review.md'),'# Accepted fixture review');save(r,'07_audit/domain_findings.json',[]);save(r,'02_echipa/roles.json',{roles:[{id:'MGR'},{id:'AUD-GOV'}]});save(r,'05_validare/experiments.json',{experiments:[{id:'E1',requirements:['R1'],metric:'m',target:'t',protocol:'p',sample:'s',owner:'MGR',auditor:'AUD-GOV',status:'planned',result:null}]});save(r,'03_plan/requirements.json',{requirements:[{id:'R1',owner:'MGR',acceptance:'t',tests:['E1']}]});save(r,'03_plan/tasks.json',{tasks:[{id:'DOC-X',owner:'MGR',auditor:'AUD-GOV',status:'accepted',dependencies:[],outputs:['evidence.txt'],acceptance:'criterion',next_action:'resume W00',attempt:1,audit_ref:'07_audit/review.md',accepted_at:new Date().toISOString(),acceptance_evidence:['evidence.txt']}]});save(r,'07_audit/REGISTRU.json',{status:'accepted',required_domains:['AUD-GOV'],findings:[],reviews:[{domain:'AUD-GOV',status:'accepted',author_agent:'writer',auditor_agent:'reviewer',report:'07_audit/review.md',findings_ref:'07_audit/domain_findings.json'}]});probe('GOV2-F04','Valid reciprocal registers, audit reference and empty checked findings',r,['validate']);
probe('GOV2-F05','Manifest final positive fixture',r,['manifest']);probe('GOV2-F06','Verify positive fixture unchanged',r,['verify']);fs.appendFileSync(path.join(r,'evidence.txt'),'alteration');probe('GOV2-F07','Verify detects artifact alteration',r,['verify']);
const hash=crypto.createHash('sha256').update(fs.readFileSync(path.join(src,'tools/manage.cjs'))).digest('hex');
fs.writeFileSync(path.join(base,'governance_r2_final_results.json'),JSON.stringify({at:new Date().toISOString(),manage_sha256:hash,scope:'isolated positive/negative final controls',results},null,2));console.log(JSON.stringify({manage_sha256:hash,results}));

